const userActions =
  pluginVariables['f5856798-485d-47be-b433-d43d771c64e1']['user']?.['user_records']?.['actions'] || [];

// Hoy en YYYY-MM-DD
const today = new Date().toISOString().split('T')[0];

// Normalizadores
const isTrue  = v => v === true  || v === 1 || v === '1' || v === 'true';

// Filtrado y mapeo de IDs (misma forma que antes)
const filteredActionIds = userActions.flatMap(action => {
  const subs = Array.isArray(action._actions) ? action._actions : [];

  return subs
    .filter(_action => {
      // Fecha (mismo criterio que tenías)
      const start = String(_action?.start_date ?? '').slice(0, 10);
      if (!start || start > today) return false;

      // Flags: tomar del hijo y, si faltan, caer al padre
      const valid_record     = _action?.valid_record     ?? action?.valid_record;
      const approved_record  = _action?.approved_record  ?? action?.approved_record;
      const pending_approval = _action?.pending_approval ?? action?.pending_approval;

      // Regla: valid_record === true AND NOT(approved_record === true OR pending_approval === true)
      return isTrue(valid_record) && !isTrue(approved_record) && !isTrue(pending_approval);
    })
    .map(() => action.id);
});

// Si quieres IDs únicos:
