// Initialize an empty array to hold all potential categories.
const categories = [];

// Ensure the variable is accessed safely and correctly.
const userActions = pluginVariables['f5856798-485d-47be-b433-d43d771c64e1']['user']?.['user_records']?.['actions'];

// Check if user actions exist and are an array
if (Array.isArray(userActions)) {
  userActions.forEach(action => {
    const actionCategories = action?._actions?.[0]?.['action_categories_id'];

    // Check if action categories exist and are an array
    if (Array.isArray(actionCategories)) {
      actionCategories.forEach(categoryGroup => 
        // Check if categoryGroup is an array
        Array.isArray(categoryGroup) && categoryGroup.forEach(categoryObj => {
          const categoryName = categoryObj?.['category'];
          // Ensure categoryName is a string and not already in the categories array
          if (typeof categoryName === 'string' && !categories.includes(categoryName)) {
            categories.push(categoryName);
          }
        })
      );
    }
  });
}

// Ensure the categories array is returned.
return categories;

// === Inputs desde Xano Auth ===
// Nota: evita poner el comentario dentro de los corchetes del índice.
const xanoUser = pluginVariables['f5856798-485d-47be-b433-d43d771c64e1']?.user;
const currentUserIdRaw = xanoUser?.id;
const actions = xanoUser?.user_records?.actions;

// Validaciones básicas
if (!currentUserIdRaw) return [];
if (!Array.isArray(actions)) return [];

// Normalizamos tipos para evitar fallos de includes por number/string
const currentUserId = String(currentUserIdRaw);

// Filtramos acciones donde ALGÚN elemento del stream NO contiene al usuario en user2_id
const filteredActions = actions.filter(action => {
  // Debe existir un array stream para evaluar (si quieres incluir sin stream, cambia a `return true`)
  if (!Array.isArray(action?.stream)) return false;

  // ¿Algún streamItem no contiene al user?
  return action.stream.some(streamItem => {
    // Tomamos user2_id como array (si faltan/son inválidos ⇒ array vacío)
    const readIds = Array.isArray(streamItem?.user2_id)
      ? streamItem.user2_id.filter(v => v != null).map(v => String(v))
      : [];

    // Incluir si el usuario NO está en user2_id
    return !readIds.includes(currentUserId);
  });
});

return filteredActions;

