const itemData = context?.item?.data;

// If itemData is a string (URL), check for PDF extension
if (typeof itemData === 'string') {
    return itemData.toLowerCase().includes('.pdf');
}

// If itemData is an object, check various properties for PDF indicators
if (typeof itemData === 'object' && itemData !== null) {
    // Check URL property
    if (itemData.url && typeof itemData.url === 'string') {
        if (itemData.url.toLowerCase().includes('.pdf')) {
            return true;
        }
    }

    // Check type property
    if (itemData.type && typeof itemData.type === 'string') {
        if (itemData.type.toLowerCase().includes('pdf')) {
            return true;
        }
    }

    // Check mime type
    if (itemData.mime && typeof itemData.mime === 'string') {
        if (itemData.mime.toLowerCase().includes('pdf')) {
            return true;
        }
    }

    // Check name property for PDF extension
    if (itemData.name && typeof itemData.name === 'string') {
        if (itemData.name.toLowerCase().includes('.pdf')) {
            return true;
        }
    }
}

// If no PDF indicators found, return false
return false;

