// Check if the current item's data contains a video URL
// Look for common video file extensions or video-related properties
const itemData = context?.item?.data;

if (!itemData) {
    return false;
}

// If itemData is a string (URL), check for video extensions
if (typeof itemData === 'string') {
    const videoExtensions = ['.mp4', '.avi', '.mov', '.wmv', '.flv', '.webm', '.mkv', '.m4v'];
    const lowerUrl = itemData.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.includes(ext));
}

// If itemData is an object, check for video-related properties
if (typeof itemData === 'object') {
    // Check if it has a URL property that contains video extensions
    if (itemData.url) {
        const videoExtensions = ['.mp4', '.avi', '.mov', '.wmv', '.flv', '.webm', '.mkv', '.m4v'];
        const lowerUrl = itemData.url.toLowerCase();
        return videoExtensions.some(ext => lowerUrl.includes(ext));
    }

    // Check for type property indicating video
    if (itemData.type && itemData.type.toLowerCase().includes('video')) {
        return true;
    }

    // Check for mime type indicating video
    if (itemData.mime && itemData.mime.toLowerCase().startsWith('video/')) {
        return true;
    }
}

// Default to false if no video indicators found
return false;

// Check if the current item data represents an image
const itemData = context?.item?.data;

if (!itemData) {
    return false;
}

// If it's a string (URL), check for image file extensions
if (typeof itemData === 'string') {
    const imageExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.svg', '.tiff', '.ico'];
    const lowerUrl = itemData.toLowerCase();
    return imageExtensions.some(ext => lowerUrl.includes(ext));
}

// If it's an object, check for image indicators
if (typeof itemData === 'object') {
    // Check URL property
    if (itemData.url && typeof itemData.url === 'string') {
        const imageExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.svg', '.tiff', '.ico'];
        const lowerUrl = itemData.url.toLowerCase();
        if (imageExtensions.some(ext => lowerUrl.includes(ext))) {
            return true;
        }
    }

    // Check type or mime properties
    if (itemData.type && typeof itemData.type === 'string') {
        const lowerType = itemData.type.toLowerCase();
        if (lowerType.includes('image') || lowerType === 'image') {
            return true;
        }
    }

    if (itemData.mime && typeof itemData.mime === 'string') {
        const lowerMime = itemData.mime.toLowerCase();
        if (lowerMime.startsWith('image/')) {
            return true;
        }
    }

    // Check name or filename properties
    if (itemData.name && typeof itemData.name === 'string') {
        const imageExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.svg', '.tiff', '.ico'];
        const lowerName = itemData.name.toLowerCase();
        if (imageExtensions.some(ext => lowerName.includes(ext))) {
            return true;
        }
    }
}

return false;

