// Obtener el action_group_id del item actual
const currentJourney = context.item.data?.['id'];

// Obtener las acciones del usuario desde el plugin de Xano Auth
const userActions = pluginVariables['f5856798-485d-47be-b433-d43d771c64e1']['user']?.['user_records']?.['actions'] || [];

// Filtrar las acciones que tienen un action_group_id igual al del item actual
const matchingActions = userActions.filter(action => action['journey_id'] === currentJourney);

// Contar las acciones que coinciden
const matchingActionsCount = matchingActions.length;

// Obtener el ID del grupo de acción del contexto del ítem
const itemId = context.item.data?.['id'];

// Filtrar las acciones que tienen el mismo action_group_id que el itemId y que están aprobadas
const filteredActions = userActions.filter(action => action['journey_id'] === itemId && action['approved_record'] === true);

// Contar el número de acciones filtradas
const countApprovedActions = filteredActions.length;

// Calculate the percentage and round it
const percentage = Math.round((countApprovedActions / matchingActionsCount) * 100);


// Retornar el resultado
return `${percentage}%`;

