// Get the current day of the week (0-6, Sunday is 0)
let currentDay = currentDate.getUTCDay();

// Calculate the number of days until next Sunday
let daysUntilNextSunday = (7 - currentDay) % 7;

// Add the number of days until next Sunday to the current date
currentDate.setUTCDate(currentDate.getUTCDate() + daysUntilNextSunday);

// Set the time to the end of the day (23:59:59)
