// Get the current date
let currentDate = new Date();

// Get the current day of the week (0-6, Sunday is 0)
let currentDay = currentDate.getUTCDay();

// Calculate the difference between the current day and the previous Monday
let difference = currentDay >= 1 ? currentDay - 1 : 6;

// Subtract the difference in days from the current date to get the date of the last Monday
currentDate.setUTCDate(currentDate.getUTCDate() - difference);

// Set the time to the beginning of the day
currentDate.setUTCHours(0, 0, 0, 0);

// Return the date of the last Monday at the beginning of the day in UTC
return currentDate.toISOString();

